# Let me look at the session file more systematically to find feedback on the Demo 1 submission
session_file = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference/play/users/u016/system/state/sessions/01a19344-8cf2-734b-8910-071c1a0cbdd4.jsonl"

with open(session_file, 'r') as f:
    json_lines = [line.strip() for line in f.readlines() if line.strip()]

# Parse each line and look for feedback
import json

found_submissions = []
for i, line in enumerate(json_lines):
    msg = json.loads(line)
    # Check if this message is a submission result
    if 'content' in msg and 'message' in msg:
        role = msg['message'].get('role', '')
        if role == 'toolResult' and msg.get('toolName') == 'ipython':
            content = json.loads(msg['content'])
            # Check if this contains feedback about submissions
            for item in content:
                if 'text' in item:
                    text = item['text']
                    if any(word in text.lower() for word in ['feedback', 'correct', 'incorrect', 'your answer', 'wrong', 'right']):
                        found_submissions.append((i, text[:200]))

print(f"Found {len(found_submissions)} potential submission feedback lines:")
for idx, text in found_submissions:
    print(f"Line {idx}: {text}")

